/*
 * LPC2148 SmartX Board - Button + LED
 * Read button on P0.16 (active low with internal pull-up)
 * Control onboard LED1 on P0.12
 */

#include <LPC214x.h>

int main() {
    IO0DIR |= (1 << 12);       // P0.12 = output (LED1)
    IO0DIR &= ~(1 << 16);      // P0.16 = input (button)
    while (1) {
        if (!(IO0PIN & (1 << 16))) {   // Button pressed (active low)
            IO0SET = (1 << 12);         // LED1 ON
        } else {
            IO0CLR = (1 << 12);         // LED1 OFF
        }
        delay_ms(50);
    }
}
